Schedule $&#123;self.name&#125;

$&#123;self.timeSlots replace=Schedule&#125;

]&#125;

Slot &#123;[
    Teacher: $&#123;self.teacher&#125;
    Room:    $&#123;self.room&#125;
    Course:  $&#123;self.course&#125;
]&#125;</code></pre>
